#!/usr/bin/env bash
# SKYBYTE Manager V2.1 community manager; review before running, Debian/Ubuntu only
# Generated by scripts/build.py from src/, lib/ and modules/. Edit source modules, then rebuild.
# The ownership marker above stays stable across manager releases.
# Installation/restore deliberately isolate transactions in subshells; dynamic locals
# remain visible to called helpers/traps and never escape to menu operations.
# shellcheck disable=SC2030,SC2031
set -Eeuo pipefail
umask 077
SCRIPT_PATH="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/$(basename -- "${BASH_SOURCE[0]}")"
MANAGER_VERSION=2.8.27
CORE_RECOMMENDED=1.14.3
BASE=/etc/singbox-v2
CONF=/etc/sing-box/config.json
SYSTEMD_DIR=/etc/systemd/system
OS_RELEASE=/etc/os-release
MANAGER_BIN=/usr/local/sbin/singbox-v2
MANAGER_LIB=/usr/local/lib/singbox-v2/singbox-v2.sh
SYSCTL_FILE=/etc/sysctl.d/90-singbox-v2-bbr.conf
META=$BASE/state.json
REPORT=$BASE/reports
BACKUP=$BASE/backups
BIN=/usr/local/bin/sing-box
LOCK=/run/singbox-v2.lock
WARP_REPO_FILE=/etc/apt/sources.list.d/skybyte-cloudflare-warp.list
WARP_KEY_FILE=/usr/share/keyrings/skybyte-cloudflare-warp.gpg
HAPROXY_BIN=/usr/sbin/haproxy
HAPROXY_RUNTIME_DIR=/run/systemd/system


